const MAP = {"🍖":"meat","💬":"conversation","🧼":"soap","🎲":"rolling-dices","🌙":"night-sleep","💞":"crowned-heart","⭐":"falling-star","❤️":"ball-heart","🛡️":"bordered-shield","🔨":"anvil","📜":"scroll-unfurled","📍":"position-marker","🏆":"trophy","🎯":"bullseye","✨":"sparkles","🧭":"compass","🕘":"sands-of-time","🪙":"coins","🍼":"baby-bottle","🪓":"wood-axe","💍":"diamond-ring","👶":"baby-face","🌿":"herbs-bundle","🗡️":"broadsword","📖":"open-book","🎵":"musical-notes","⚔️":"crossed-swords","🍲":"cooking-pot","🍞":"bread","🗣️":"conversation","🛋️":"sofa","🛁":"bathtub","💪":"biceps","🤫":"silence","🎉":"party-popper","🔍":"magnifying-glass","☁️":"fluffy-cloud","😴":"sleepy","💛":"hearts","🛠️":"hammer-nails","🪨":"rock","⚖️":"scales"};
const KEYS = Object.keys(MAP).sort((a, b) => b.length - a.length);
const RE = new RegExp(KEYS.map((k) => k.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|') + '|gi:[a-z-]+|face:[0-4]', 'g');

// five simple painted mood faces (0 = sad ... 4 = joyful), drawn to match the bold gold glyph look
const MOUTH = ['M176 360q80-70 160 0', 'M176 350q80-40 160 0', 'M186 350h140', 'M176 330q80 40 160 0', 'M170 320q86 90 172 0z'];
const face = (i) => '<svg class="gi" viewBox="0 0 512 512" fill="none" stroke="currentColor" stroke-width="34" stroke-linecap="round" stroke-linejoin="round"><circle cx="256" cy="256" r="210"/>' +
  '<circle cx="186" cy="215" r="12" fill="currentColor"/><circle cx="326" cy="215" r="12" fill="currentColor"/><path d="' + MOUTH[i] + '"' + (i === 4 ? ' fill="currentColor"' : '') + '/></svg>';
export const svg = (name) => (BODY[name] ? '<svg class="gi" viewBox="0 0 512 512" fill="currentColor" aria-hidden="true">' + BODY[name] + '</svg>' : '');
export const moodIcon = (m) => face(m > 0.82 ? 4 : m > 0.64 ? 3 : m > 0.46 ? 2 : m > 0.3 ? 1 : 0);
// replace emoji (and gi:name / face:n tokens) in an HTML string with inline SVG icons
export const ic = (html) => String(html).replace(RE, (t) => (t.startsWith('gi:') ? svg(t.slice(3)) : t.startsWith('face:') ? face(+t[5]) : svg(MAP[t])));
